function boilAltitude(h){
  h=+h; if(isNaN(h)||h<0) return {error:'海拔须为非负数字（米）'};
  var p = 101.325 * Math.pow(1 - 2.25577e-5*h, 5.25588);
  if(!(p>0)) return {error:'海拔过高，超出近似范围'};
  var r = boilPressure(p);
  return {c:r.c, f:r.f, altitude:h};
}
function boilPressure(p){
  p=+p; if(isNaN(p)||p<=0) return {error:'压强须为正数（kPa）'};
  var mmHg=p*7.50062;
  if(mmHg<=0) return {error:'压强过低'};
  var T = 1730.63/(8.07131 - Math.log10(mmHg)) - 233.426;
  T=Math.round(T*10)/10;
  return {c:T, f:Math.round((T*9/5+32)*10)/10, kPa:p};
}
var EXPORTS={boilAltitude:boilAltitude, boilPressure:boilPressure};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BoilingPointForgePure = EXPORTS; }
